#!/usr/bin/env python3
"""Generate runtime-build trap stubs for every symbol a forced link left unresolved."""
import argparse
from pathlib import Path
import re


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("log", type=Path, help="Output of cc.py --link --allow-unresolved")
    parser.add_argument("output", type=Path, help="C source to write")
    args = parser.parse_args()
    symbols = sorted(set(re.findall(r"unresolved external symbol (\S+)", args.log.read_text(errors="replace"))))
    lines = [
        "// Generated by tools/traps.py: each unresolved symbol is an alternate name for a trap.",
        "#include <intrin.h>",
        "#pragma intrinsic(_ReturnAddress)",
        "void __cdecl SagaRuntime_Trap(const char *symbol, void *caller);",
    ]
    for index, symbol in enumerate(symbols):
        lines += [
            f'void __cdecl SagaTrap_{index}(void) {{ SagaRuntime_Trap("{symbol}", _ReturnAddress()); }}',
            f'#pragma comment(linker, "/alternatename:{symbol}=_SagaTrap_{index}")',
        ]
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text("\n".join(lines) + "\n")
    print(f"Generated {len(symbols)} trap stubs", flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
